36	            .conn
37	            .prepare(
38	                "SELECT id, session_id, rule_id, severity, confidence, title, message
39	                 FROM findings
40	                 ORDER BY confidence DESC, id DESC
41	                 LIMIT ?1",
42	            )
43	            .map_err(StoreError::Sqlite)?;
44	
45	        let rows = stmt
46	            .query_map(params![limit as i64], |row| {
47	                Ok(FindingReadModel {
