1	use lumen_model::OrchestratorKind;
2	
3	/// Detects the orchestrator from a byte sample of the log file header (first 2048 bytes).
4	pub fn detect_orchestrator(sample_bytes: &[u8]) -> Option<OrchestratorKind> {
5	    let sample_str = std::str::from_utf8(sample_bytes).unwrap_or("");
6	
7	    if sample_str.contains("\"sessionId\"") && sample_str.contains("\"parentUuid\"") {
8	        return Some(OrchestratorKind::ClaudeCode);
9	    }
10	
11	    if sample_str.contains("\"step_index\"")
12	        && (sample_str.contains("\"source\":\"USER_EXPLICIT\"")
13	            || sample_str.contains("\"source\":\"MODEL\"")
14	            || sample_str.contains("\"PLANNER_RESPONSE\""))
15	    {
16	        return Some(OrchestratorKind::Antigravity);
17	    }
18	
19	    if sample_str.contains("\"type\":\"event_msg\"") || sample_str.contains("\"type\":\"response_item\"") {
20	        return Some(OrchestratorKind::Codex);
21	    }
22	
23	    if sample_str.contains("\"action\":\"run\"")
24	        || sample_str.contains("\"action\": \"run\"")
25	        || sample_str.contains("\"observation\":")
26	        || sample_str.contains("\"action\":\"message\"")
27	    {
28	        return Some(OrchestratorKind::OpenCode);
29	    }
30	
31	    None
32	}
33	
