39	    fn test_detect_claude_code() {
40	        let sample = b"{\"type\":\"assistant\",\"sessionId\":\"ef175eb8-0825-4122-934b\",\"parentUuid\":\"turn-0\",\"message\":{}}";
41	        assert_eq!(detect_orchestrator(sample), Some(OrchestratorKind::ClaudeCode));
42	    }
43	
44	    #[test]
45	    fn test_detect_claude_code_sessionid_alone_is_not_claude_code() {
46	        let sample = b"{\"sessionId\":\"ef175eb8-0825-4122-934b\"}";
47	        assert_ne!(detect_orchestrator(sample), Some(OrchestratorKind::ClaudeCode));
48	    }
