67	        // (OpenCodeAdapter::parse_stream builds a CanonicalTurn from it) that detect_orchestrator
68	        // must also recognize so the two independently-coded paths cannot drift apart.
69	        let sample = b"{\"action\":\"message\",\"source\":\"assistant\",\"args\":{\"content\":\"done\"}}";
70	        assert_eq!(detect_orchestrator(sample), Some(OrchestratorKind::OpenCode));
71	    }
