1	use chrono::{DateTime, Utc};
2	use compact_str::CompactString;
3	use lumen_model::*;
4	use smallvec::SmallVec;
5	use std::io::BufRead;
6	
7	use crate::adapter::{AdapterCapabilities, IngestionError, SessionAdapter};
8	use crate::fingerprint::detect_orchestrator;
9	
10	pub struct ClaudeCodeAdapter;
11	
12	impl SessionAdapter for ClaudeCodeAdapter {
13	    fn name(&self) -> &'static str {
14	        "claude-code"
15	    }
16	
17	    fn matches_fingerprint(&self, sample: &str) -> bool {
18	        // Delegates to detect_orchestrator (the single source of truth for orchestrator
19	        // precedence) instead of maintaining an independently-coded condition that can drift.
20	        detect_orchestrator(sample.as_bytes()) == Some(OrchestratorKind::ClaudeCode)
21	    }
22	
23	    fn capabilities(&self) -> AdapterCapabilities {
24	        AdapterCapabilities {
25	            has_token_usage: true,
26	            has_tool_results: true,
27	            has_shell_commands: true,
28	            has_file_events: true,
29	            has_lifecycle_hooks: true,
30	            supports_incremental_offsets: true,
31	            supports_cost_estimation: true,
32	        }
33	    }
34	
35	    fn parse_stream<'a>(&self, reader: Box<dyn BufRead + 'a>) -> Result<CanonicalTranscript, IngestionError> {
36	        let mut session_id = CompactString::new("unknown");
37	        let mut model_family = CompactString::new("claude-3-5-sonnet-20241022");
38	        let mut turns = Vec::new();
39	        let mut started_at = Utc::now();
40	        let mut ended_at = Utc::now();
41	        let mut has_start = false;
42	
43	        let mut total_input: u64 = 0;
44	        let mut total_output: u64 = 0;
45	        let mut total_cache_creation: u64 = 0;
46	        let mut total_cache_read: u64 = 0;
47	        let mut parse_failures: SmallVec<[ParseFailureRecord; 2]> = SmallVec::new();
48	        let mut otel_conversation_id: Option<CompactString> = None;
49	
50	        'lines: for (idx, line_res) in reader.lines().enumerate() {
51	            let line = match line_res {
52	                Ok(l) => l,
53	                Err(e) => return Err(IngestionError::Io(e)),
54	            };
55	
56	            let trimmed = line.trim();
57	            let clean_line = trimmed.strip_prefix('\u{FEFF}').unwrap_or(trimmed).trim();
58	            if clean_line.is_empty() {
59	                continue;
60	            }
61	
62	            let val: serde_json::Value = match serde_json::from_str(clean_line) {
63	                Ok(v) => v,
64	                Err(e) => {
65	                    // Skip corrupted or incomplete JSON lines gracefully, but record the
66	                    // failure so it survives the parse_stream call (CRIT-LUMEN-025).
67	                    parse_failures.push(ParseFailureRecord {
68	                        session_id: session_id.clone(),
69	                        line_number: idx + 1,
70	                        byte_offset: 0,
71	                        error: CompactString::new(e.to_string()),
72	                    });
73	                    continue;
74	                }
75	            };
76	
77	            if !val.is_object() {
78	                continue;
79	            }
80	
81	            // CRIT-LUMEN-163: an explicit JSON null on one of these known fields is malformed,
82	            // not a valid empty/zero value -- reject the whole line rather than silently
83	            // treating the null the same as an absent field.
84	            for field in [
85	                "id",
86	                "cwd",
87	                "model",
88	                "sessionId",
89	                "requestId",
90	                "version",
91	                "costUSD",
92	                "cache_creation_input_tokens",
93	                "cache_read_input_tokens",
94	            ] {
95	                if val.get(field).map(|v| v.is_null()).unwrap_or(false) {
96	                    parse_failures.push(ParseFailureRecord {
97	                        session_id: session_id.clone(),
98	                        line_number: idx + 1,
99	                        byte_offset: 0,
100	                        error: CompactString::new(format!("explicit null on field '{field}'")),
101	                    });
102	                    continue 'lines;
103	                }
104	            }
105	
106	            // CRIT-LUMEN-026: entries with is_sidechain=true belong to a subagent/parallel
107	            // branch, distinct from the main chain -- exclude them from the main transcript's
108	            // turns entirely.
109	            let is_sidechain = val.get("is_sidechain").and_then(|v| v.as_bool()).unwrap_or(false);
110	            if is_sidechain {
111	                continue;
112	            }
113	
114	            // CRIT-LUMEN-164: otel_conversation_id is set from the first non-sidechain entry's
115	            // requestId encountered in file order, and never overwritten thereafter.
116	            if otel_conversation_id.is_none() {
117	                if let Some(rid) = val.get("requestId").and_then(|v| v.as_str()) {
118	                    otel_conversation_id = Some(CompactString::new(rid));
119	                }
120	            }
121	
122	            // Extract session ID
123	            if let Some(s) = val.get("sessionId").and_then(|v| v.as_str()) {
124	                if session_id == "unknown" {
125	                    session_id = CompactString::new(s);
126	                }
127	            }
128	
129	            // Extract timestamp from message or attachment
130	            if let Some(ts_str) = val.get("timestamp").and_then(|v| v.as_str()) {
131	                if let Ok(ts) = DateTime::parse_from_rfc3339(ts_str) {
132	                    let utc_ts = ts.with_timezone(&Utc);
133	                    if !has_start {
134	                        started_at = utc_ts;
135	                        has_start = true;
136	                    }
137	                    ended_at = utc_ts;
138	                }
139	            }
140	
141	            let line_type = val.get("type").and_then(|v| v.as_str()).unwrap_or("");
142	
143	            if line_type == "assistant" {
144	                if let Some(message) = val.get("message").and_then(|m| m.as_object()) {
145	                    if let Some(m) = message.get("model").and_then(|v| v.as_str()) {
146	                        if !m.starts_with("<synthetic>") {
147	                            model_family = CompactString::new(m);
148	                        }
149	                    }
150	
151	                    // Extract token usage
152	                    let mut turn_usage = None;
153	                    if let Some(u) = message.get("usage").and_then(|u| u.as_object()) {
154	                        let in_tok = u.get("input_tokens").and_then(|v| v.as_u64()).unwrap_or(0);
155	                        let out_tok = u.get("output_tokens").and_then(|v| v.as_u64()).unwrap_or(0);
156	                        let cache_write = u.get("cache_creation_input_tokens").and_then(|v| v.as_u64()).unwrap_or(0);
157	                        let cache_read = u.get("cache_read_input_tokens").and_then(|v| v.as_u64()).unwrap_or(0);
158	
159	                        total_input += in_tok;
160	                        total_output += out_tok;
161	                        total_cache_creation += cache_write;
162	                        total_cache_read += cache_read;
163	
164	                        turn_usage = Some(TurnTokenUsage {
165	                            input_tokens: in_tok,
166	                            output_tokens: out_tok,
167	                            cache_creation_tokens: cache_write,
168	                            cache_read_tokens: cache_read,
169	                        });
170	                    }
171	
172	                    // Extract tool calls and text
173	                    let mut tool_calls = SmallVec::new();
174	                    let mut turn_text = None;
175	
176	                    if let Some(contents) = message.get("content").and_then(|c| c.as_array()) {
177	                        for block in contents {
178	                            if let Some(block_obj) = block.as_object() {
179	                                let block_type = block_obj.get("type").and_then(|t| t.as_str()).unwrap_or("");
180	                                if block_type == "tool_use" {
181	                                    let id = block_obj.get("id").and_then(|v| v.as_str()).unwrap_or("");
182	                                    let name = block_obj.get("name").and_then(|v| v.as_str()).unwrap_or("");
183	                                    if !id.is_empty() || !name.is_empty() {
184	                                        let input = block_obj.get("input").cloned().unwrap_or(serde_json::Value::Null);
185	                                        let intent = parse_tool_intent(name, &input);
186	
187	                                        tool_calls.push(CanonicalToolCall {
188	                                            call_id: CompactString::new(id),
189	                                            tool_name: CompactString::new(name),
190	                                            intent,
191	                                            raw_arguments: input,
192	                                        });
193	                                    }
194	                                } else if block_type == "text" {
195	                                    if let Some(txt) = block_obj.get("text").and_then(|v| v.as_str()) {
196	                                        turn_text = Some(txt.to_string());
197	                                    }
198	                                }
199	                            }
200	                        }
201	                    } else if let Some(txt) = message.get("content").and_then(|c| c.as_str()) {
202	                        turn_text = Some(txt.to_string());
203	                    }
204	
205	                    // Only push if turn has substantive content, tools, or usage
206	                    if turn_usage.is_some() || !tool_calls.is_empty() || turn_text.is_some() {
207	                        turns.push(CanonicalTurn {
208	                            attribution: None,
209	                            turn_index: turns.len(),
210	                            role: TurnRole::Assistant,
211	                            timestamp: ended_at,
212	                            latency_ms: 0,
213	                            text: turn_text,
214	                            tool_calls,
215	                            tool_results: SmallVec::new(),
216	                            usage: turn_usage,
217	                        });
218	                    }
219	                }
220	            } else if line_type == "user" {
221	                let mut tool_results = SmallVec::new();
222	                let mut user_text = None;
223	
224	                if let Some(msg) = val.get("message") {
225	                    if let Some(txt) = msg.get("content").and_then(|c| c.as_str()) {
226	                        user_text = Some(txt.to_string());
227	                    } else if let Some(arr) = msg.get("content").and_then(|c| c.as_array()) {
228	                        for b in arr {
229	                            let block_type = b.get("type").and_then(|t| t.as_str()).unwrap_or("");
230	                            if block_type == "tool_result" {
231	                                let tool_use_id = b.get("tool_use_id").and_then(|v| v.as_str()).unwrap_or("");
232	                                let is_error = b.get("is_error").and_then(|v| v.as_bool()).unwrap_or(false);
233	                                let content_str = b.get("content").and_then(|v| v.as_str()).unwrap_or("");
234	                                tool_results.push(CanonicalToolResult {
235	                                    call_id: CompactString::new(tool_use_id),
236	                                    output_bytes: content_str.len(),
237	                                    line_count: content_str.lines().count(),
238	                                    is_error,
239	                                    error_class: if is_error { Some(CompactString::new("ToolError")) } else { None },
240	                                    truncated_output: None,
241	                                    otel_span_id: None,
242	                                });
243	                            } else if block_type == "text" {
244	                                if let Some(txt) = b.get("text").and_then(|t| t.as_str()) {
245	                                    user_text = Some(txt.to_string());
246	                                }
247	                            }
248	                        }
249	                    }
250	                } else if let Some(txt) = val.get("text").and_then(|v| v.as_str()) {
251	                    user_text = Some(txt.to_string());
252	                }
253	
254	                if !tool_results.is_empty() {
255	                    turns.push(CanonicalTurn {
256	                        attribution: None,
257	                        turn_index: turns.len(),
258	                        role: TurnRole::ToolResult,
259	                        timestamp: ended_at,
260	                        latency_ms: 0,
261	                        text: None,
262	                        tool_calls: SmallVec::new(),
263	                        tool_results,
264	                        usage: None,
265	                    });
266	                } else if let Some(text) = user_text {
267	                    turns.push(CanonicalTurn {
268	                        attribution: None,
269	                        turn_index: turns.len(),
270	                        role: TurnRole::User,
271	                        timestamp: ended_at,
272	                        latency_ms: 0,
273	                        text: Some(text),
274	                        tool_calls: SmallVec::new(),
275	                        tool_results: SmallVec::new(),
276	                        usage: None,
277	                    });
278	                }
279	            }
280	        }
