10	pub struct CodexAdapter;
11	
12	impl SessionAdapter for CodexAdapter {
13	    fn name(&self) -> &'static str {
14	        "codex"
15	    }
16	
17	    fn matches_fingerprint(&self, sample: &str) -> bool {
18	        // CRIT-LUMEN-108: delegates to detect_orchestrator (single source of truth, including
19	        // precedence over earlier-checked orchestrators) instead of an independent condition.
20	        detect_orchestrator(sample.as_bytes()) == Some(OrchestratorKind::Codex)
21	    }
22	
23	    fn capabilities(&self) -> AdapterCapabilities {
24	        AdapterCapabilities {
25	            has_token_usage: true,
26	            has_tool_results: true,
27	            has_shell_commands: true,
28	            has_file_events: true,
29	            has_lifecycle_hooks: false,
30	            supports_incremental_offsets: false,
31	            supports_cost_estimation: true,
32	        }
33	    }
34	
35	    fn parse_stream<'a>(&self, reader: Box<dyn BufRead + 'a>) -> Result<CanonicalTranscript, IngestionError> {
36	        let mut session_id = CompactString::new("codex-session");
37	        let model_family = CompactString::new("gpt-4o");
38	        let started_at = Utc::now();
39	        let mut ended_at = started_at;
40	
41	        let mut turns = Vec::new();
42	        let mut parse_failures: SmallVec<[ParseFailureRecord; 2]> = SmallVec::new();
43	        let mut service_tier: Option<CompactString> = None;
44	
45	        // CRIT-LUMEN-110: Codex token_count events carry cumulative running totals, not
46	        // per-line deltas -- these are last-write values, never summed.
47	        let mut input_tokens = 0u64;
48	        let mut output_tokens = 0u64;
49	        let mut reasoning_output_tokens = 0u64;
50	
51	        for (idx, line_res) in reader.lines().enumerate() {
52	            let line = match line_res {
53	                Ok(l) => l,
54	                Err(e) => return Err(IngestionError::Io(e)),
55	            };
56	
57	            let trimmed = line.trim();
58	            if trimmed.is_empty() {
59	                continue;
60	            }
61	
62	            let val: serde_json::Value = match serde_json::from_str(trimmed) {
63	                Ok(v) => v,
64	                Err(e) => {
65	                    parse_failures.push(ParseFailureRecord {
66	                        session_id: session_id.clone(),
67	                        line_number: idx + 1,
68	                        byte_offset: 0,
69	                        error: CompactString::new(e.to_string()),
70	                    });
71	                    continue;
72	                }
73	            };
74	
75	            if let Some(ts_str) = val.get("timestamp").and_then(|v| v.as_str()) {
76	                if let Ok(ts) = DateTime::parse_from_rfc3339(ts_str) {
77	                    ended_at = ts.with_timezone(&Utc);
78	                }
79	            }
80	
81	            // Only event_msg envelope lines carry the payload shapes this adapter understands.
82	            if val.get("type").and_then(|v| v.as_str()) != Some("event_msg") {
83	                continue;
84	            }
85	
86	            let Some(payload) = val.get("payload") else {
87	                continue;
88	            };
89	
90	            match payload.get("type").and_then(|v| v.as_str()) {
91	                Some("item_completed") => {
92	                    if let Some(tid) = payload.get("thread_id").and_then(|v| v.as_str()) {
93	                        session_id = CompactString::new(tid);
94	                    }
95	
96	                    let item = payload.get("item");
97	                    let item_type = item.and_then(|i| i.get("type")).and_then(|t| t.as_str()).unwrap_or("");
98	                    let role = match item_type {
99	                        "UserMessage" => TurnRole::User,
100	                        "AgentMessage" => TurnRole::Assistant,
101	                        "CommandExecution" | "Reasoning" => TurnRole::ToolResult,
102	                        _ => TurnRole::System,
103	                    };
104	                    let text = item.and_then(|i| i.get("text")).and_then(|t| t.as_str()).map(|s| s.to_string());
105	
106	                    turns.push(CanonicalTurn {
107	                        attribution: None,
108	                        turn_index: turns.len(),
109	                        role,
110	                        timestamp: ended_at,
111	                        latency_ms: 0,
112	                        text,
113	                        tool_calls: SmallVec::new(),
114	                        tool_results: SmallVec::new(),
115	                        usage: None,
116	                    });
117	                }
118	                Some("token_count") => {
119	                    if let Some(usage) = payload.get("total_token_usage") {
120	                        input_tokens = usage.get("input_tokens").and_then(|v| v.as_u64()).unwrap_or(input_tokens);
121	                        output_tokens = usage.get("output_tokens").and_then(|v| v.as_u64()).unwrap_or(output_tokens);
122	                        reasoning_output_tokens = usage
123	                            .get("reasoning_output_tokens")
124	                            .and_then(|v| v.as_u64())
125	                            .unwrap_or(reasoning_output_tokens);
126	                    }
127	                    // No total_token_usage on this payload: leave the running totals as-is.
128	                }
129	                Some("thread_settings_applied") => {
130	                    service_tier = payload
131	                        .get("thread_settings")
132	                        .and_then(|ts| ts.get("service_tier"))
133	                        .and_then(|v| v.as_str())
134	                        .map(CompactString::new);
135	                }
136	                _ => {}
137	            }
138	        }
139	
140	        let wall_duration = (ended_at - started_at).num_milliseconds().max(0) as u64;
141	
142	        let pricing_input = TurnPricingInput {
143	            usage: TurnTokenUsage {
144	                input_tokens,
145	                output_tokens,
146	                cache_creation_tokens: 0,
147	                cache_read_tokens: 0,
148	            },
149	            timestamp: ended_at,
150	            tier: service_tier.clone(),
151	        };
152	
153	        let mut economics =
154	            TokenEconomics::calculate(&[pricing_input], &model_family, &PricingTable::seed(), None);
155	        // TurnPricingInput/TurnTokenUsage carry no reasoning-tokens field, so this last-write
156	        // value (CRIT-LUMEN-110) is applied to the computed economics afterward.
157	        economics.reasoning_output_tokens = reasoning_output_tokens;
158	
159	        Ok(CanonicalTranscript {
160	            session_id,
161	            parent_session_id: None,
162	            subagent_role: None,
163	            orchestrator: OrchestratorKind::Codex,
164	            model_family: model_family.clone(),
165	            timing: ExecutionTiming {
166	                started_at,
167	                ended_at,
168	                wall_duration_ms: wall_duration,
169	                active_duration_ms: wall_duration,
170	                idle_duration_ms: 0,
171	                idle_gap_count: 0,
172	            },
173	            economics,
174	            turns,
175	            subagents: Vec::new(),
176	            extracted_schemas: SmallVec::new(),
177	            detected_anomalies: SmallVec::new(),
178	            otel_conversation_id: None,
179	            service_tier,
180	            parse_failures,
181	        })
182	    }
183	}
